"""讀取工具帶 `item` 時的單項明細：詳細表一列的數量、單價、複價，有單價分析就列組成與每一列能不能改。

能不能用 `pcces_write_budget` 的 component 改，不另寫一套規則：拿寫入工具同一套檢查
（`edit._plan_component`、`edit._plan_analyses`）對每一列各試改一次數量、一次單價，被擋下的理由
（`EditError.brief`）就是這裡標的原因。兩支工具才不會一支說能改、另一支拒寫。試改只跑檢查，不動模型。

XML 與資料庫兩支讀取工具共用：資料庫那一路先組出同樣的 `ETenderDocument`（`db.budget.read_document`）。
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import analysis as an
from .document import ETenderDocument, Item
from .edit import (
    EditError, ItemEdit, _CompPlan, _analysis_codes, _copies, _has_analysis, _hint, _index, _kind, _name, _no,
    _plan_analyses, _plan_component, resolve,
)

# 試改用的值：整數 1 的位數檢查一定過，擋下來的只會是規則本身
_PROBE = Decimal(1)


@dataclass
class SharedUse:
    """一般工料單價全案共用：還有哪個分析（與詳細表哪幾項）用到同一個工料。"""

    code: str
    name: str
    items: list[str]


@dataclass
class ComponentRow:
    """單價分析的一列組成。`quantity_block`／`price_block` 是 None＝可以用 component 改，否則是不能改的原因。"""

    no: int
    code: str
    name: str
    unit: str
    kind: str
    quantity: Decimal | None
    price: Decimal | None
    amount: Decimal | None
    percent: Decimal | None
    quantity_block: str | None = None
    price_block: str | None = None
    shared: list[SharedUse] = field(default_factory=list)


@dataclass
class AnalysisView:
    code: str
    name: str
    unit: str
    price: Decimal | None
    output_quantity: str
    items: list[str]  # 詳細表用到這個分析的項次（同一分析被幾列用到就有幾份）
    digits: an.Digits
    rows: list[ComponentRow]
    block: str | None = None  # 整個分析都不能用 component 改的原因；有值時各列不另標


@dataclass
class ChildLine:
    path: str
    name: str
    hint: str
    amount: Decimal | None


@dataclass
class ItemView:
    path: str
    name: str
    kind: str
    unit: str
    quantity: Decimal | None
    price: Decimal | None
    amount: Decimal | None
    ref_item_code: str
    quantity_decimals: int  # 詳細表 quantityDisplayDecimal，改這一項數量時的上限
    children: list[ChildLine] | None = None  # 母項才有
    analysis: AnalysisView | None = None
    has_analysis: bool = False  # 標成有單價分析；analysis 是 None 時代表單價分析表找不到


def _unit(it: Item) -> str:
    return (it.value("Unit", "zh-TW") or "").strip()


def _probe(doc: ETenderDocument, path: str, row: Item, what: str, idx, codes: set[str], d: an.Digits) -> str | None:
    """用寫入工具的檢查試改這一列一次；擋下來就回理由。"""
    e = ItemEdit(path, component=an.code(row), **{what: _PROBE})
    try:
        plan = _plan_component(doc, e, idx, codes, d)
        _plan_analyses(doc, [plan], d, idx)
    except EditError as exc:
        return exc.brief
    return None


def item_view(doc: ETenderDocument, path: str) -> ItemView:
    """項次找不到、不唯一時丟 `EditError`（訊息列出那一層可選的項次，跟寫入工具同一支 `resolve`）。"""
    idx = _index(doc)
    _, it = resolve(doc, path, idx)
    codes = _analysis_codes(doc)
    p = idx.path(it)
    acode = it.attrs.get("refItemCode", "").strip()
    view = ItemView(
        p, _name(it), _kind(it), _unit(it), it.decimal("Quantity"), it.decimal("Price"), it.decimal("Amount"), acode,
        int(doc.detail_list.attrs.get("quantityDisplayDecimal", "0") or 0),
    )
    if it.children:
        view.children = [ChildLine(idx.path(c), _name(c), _hint(c, codes), c.decimal("Amount"))
                         for c in it.children if _no(c)]
        return view
    if not _has_analysis(it, codes):
        return view
    view.has_analysis = True
    copies = _copies(doc, acode)
    if not copies:
        return view
    w, cbl = copies[0], doc.cost_breakdown_list
    d = an.digits(cbl)
    leaves: dict[str, list[str]] = {}
    for _, x in doc.detail_list.iter_items():
        if not x.children:
            leaves.setdefault(x.attrs.get("refItemCode", "").strip(), []).append(idx.path(x))
    av = AnalysisView(acode, an.name(w), _unit(w), w.decimal("Price"), w.attrs.get("analysisOutputQuantity", "1").strip() or "1",
                      leaves.get(acode, []), d, [])
    view.analysis = av

    # 整個分析的關卡（itemKind、份數、被當巢狀、規則重現不了）跟哪一列無關，先試一次；過不了就不逐列標
    try:
        if _kind(it) != "analysis":
            _plan_component(doc, ItemEdit(p, quantity=_PROBE, component=an.code(w.children[0]) if w.children else ""),
                            idx, codes, d)
        _plan_analyses(doc, [_CompPlan(p, acode, 0, "", an.VARIABLE_KIND, _PROBE, None)], d, idx)
    except EditError as exc:
        av.block = exc.brief

    for n, c in enumerate(w.children, 1):
        row = ComponentRow(n, an.code(c), an.name(c), _unit(c), an.kind(c), c.decimal("Quantity"), c.decimal("Price"),
                           c.decimal("Amount"), c.decimal("Percent"))
        if av.block is None:
            row.quantity_block = _probe(doc, p, c, "quantity", idx, codes, d)
            row.price_block = _probe(doc, p, c, "price", idx, codes, d)
        if row.kind == an.GENERAL_KIND:
            seen: set[str] = set()
            for w2 in cbl.items:
                c2 = an.code(w2)
                if c2 != acode and c2 not in seen and any(an.code(x) == row.code for x in w2.children):
                    seen.add(c2)
                    row.shared.append(SharedUse(c2, an.name(w2), leaves.get(c2, [])))
        av.rows.append(row)
    return view
